                        "${policy.dailyPenaltyTiers.tier1Pct}% / " +
                        "${policy.dailyPenaltyTiers.tier2Pct}% / " +
                        "${policy.dailyPenaltyTiers.tier3Pct}% / " +
                        "${policy.dailyPenaltyTiers.tier4Pct}%",
