            Text(
                text = "${stringResource(R.string.admin_policy_section_slots)}: " +
                        "Slot 2=${policy.slotFees.slot2}, Slot 3=${policy.slotFees.slot3}, Slot 4+=${policy.slotFees.slot4Plus} " +
