    if (!isResolvingPending) {
        if (currentCamp?.isPaused == true) {
            isPushActionInProgress.set(false)
            _uiState.update {
                it.copy(
                    isPushLoading = false,
                    pushError = localizer.get(R.string.oad_push_paused_warning)
